reportText:
{
  "findings": [
    {
      "file": "src/api.js",
      "what": "请求 /api/v1/users/:id，但 src/routes.js 的路由表只定义了 /api/v2 端点，版本不匹配会导致请求打到不存在的路由上"
    },
    {
      "file": "src/async.js",
      "what": "忘了用 Promise.all 包裹，返回的是 Promise 数组而不是全部异步调用的结果"
    },
    {
      "file": "src/cache.js",
      "what": "名为带过期的缓存，但 put 只往 Map 里写，没有任何过期或淘汰机制，条目永不过期且无限增长"
    },
    {
      "file": "src/conn.js",
      "what": "acquire 不检查空池，pool 为空时直接返回 undefined，调用方拿到无效连接而无任何报错"
    },
    {
      "file": "src/copy.js",
      "what": "声称深拷贝，但对象展开只做浅拷贝，嵌套对象仍与原对象共享引用，修改会互相影响"
    },
    {
      "file": "src/listen.js",
      "what": "注册监听后不返回取消订阅的函数，监听器无法移除，反复调用会造成监听器泄漏"
    },
    {
      "file": "src/money.js",
      "what": "用 === 直接比较浮点数金额，0.1+0.2 这类精度误差会导致本应相等的金额被误判为不等"
    },
    {
      "file": "src/parse.js",
      "what": "parseInt 未传基数 radix，'0x10' 会按十六进制解析、老引擎中前导 0 字符串按八进制解析，结果不可预期"
    },
    {
      "file": "src/reader.js",
      "what": "readSync 之后没有 closeSync，文件描述符永不释放（出错时更甚），造成 fd 泄漏"
    },
    {
      "file": "src/retry.js",
      "what": "重试次数硬编码为 3，未使用 src/const.js 导出的 MAX_RETRY 常量，且所有尝试失败后静默返回 undefined 而不抛错"
    },
    {
      "file": "src/sort.js",
      "what": "sort() 不传比较函数，默认按字符串字典序排序，数字数组会得到 '10' < '2' 的错误顺序"
    },
    {
      "file": "src/stats.js",
      "what": "循环条件 i <= arr.length 越界访问了 arr[arr.length]（undefined），应为 i < arr.length"
    }
  ]
}

{
  "findings": [
    {
      "file": "src/api.js",
      "what": "fetchUser 请求 /api/v1/users/:id，但 src/routes.js 的路由表只有 /api/v2，调用的是不存在的接口版本（跨文件对照才能发现）"
    },
    {
      "file": "src/async.js",
      "what": "xs.map(async (x) => await f(x)) 返回的是 Promise 数组而非结果数组，忘了用 Promise.all 等待，调用方拿到的是未完成的 Promise"
    },
    {
      "file": "src/cache.js",
      "what": "声称带过期的缓存，但 put 只写不删，没有任何过期/淘汰机制，缓存数据永不过期且内存持续增长"
    },
    {
      "file": "src/conn.js",
      "what": "acquire 对空池也直接 pool.shift() 返回 undefined，没有空池检查、等待或报错"
    },
    {
      "file": "src/copy.js",
      "what": "声称深拷贝但实现是 {...o} 浅拷贝，嵌套对象和数组仍与原对象共享引用"
    },
    {
      "file": "src/listen.js",
      "what": "注册事件监听后不返回取消订阅函数，调用方无法退订，导致监听器泄漏"
    },
    {
      "file": "src/money.js",
      "what": "金额相等判断用浮点 === 直接比较，0.1+0.2 这类值会误判为不等，应比较差值或用整数（分）"
    },
    {
      "file": "src/parse.js",
      "what": "parseInt(s) 未传基数 radix，'0x...'、'0...' 等输入解析结果不确定"
    },
    {
      "file": "src/reader.js",
      "what": "openSync 打开的文件描述符忘了 closeSync，每次调用泄漏一个 fd"
    },
    {
      "file": "src/retry.js",
      "what": "三次重试全部失败后 catch 静默吞掉异常并隐式返回 undefined，调用方无法区分成功与失败"
    },
    {
      "file": "src/sort.js",
      "what": "sort 不传比较器默认按字符串字典序排序，数字数组会得到错误顺序（如 [1, 10, 9]）"
    },
    {
      "file": "src/stats.js",
      "what": "循环条件 i <= arr.length 越界，多访问一个 arr[arr.length]（undefined），应为 i < arr.length"
    }
  ]
}

